<script setup lang="ts">
definePageMeta({ title: 'Explore' });
useSeoMeta({ title: 'Explore' });
interface Place { name: string; category: string; area?: string; description?: string; address: string; lat?: number; lon?: number; img?: string; previewImage?:string; mrt?: {name:string;dist:number}; mrtOptions?: {name:string;entrance:string;access:string}[]; bus?:{code:string;name:string;dist?:number;access?:string}; transportStations?:string[]; transportSources?:string[]; officialUrl?:string; datasetUrl?:string; note?:string; checkedAt?:string; gate?:string; distance?:number; closed?:boolean; transportPending?:boolean; walkRoute?:{url:string;meters:number;minutes:number;endpoint:string;steps:string[];warnings:string[];kind:string}; }
const { data: attractions } = await useLazyFetch<{items:Place[]}>('/attractions.json', {server:false});
const { data: additions } = await useLazyFetch<{items:Place[];coverage?:{parkDestinations:number;excludedConnectorTrails:number;libraries:number;closedLibraries:number;parkTransportPending:number}}>('/explore-places.json', {server:false});
const { data: rail } = await useLazyFetch<{lines:{code:string;color:string;stations:{name:string;lat:number;lon:number}[]}[]}>('/mrt-lines.json', {server:false});
const query=ref(''); const suggestionsOpen=ref(false); const activeSuggestion=ref(-1); const category=ref('All'); const expanded=ref<string|null>(null); const limit=ref(12);
function fmt(m:number){return m<1000?`${Math.round(m/10)*10} m`:`${(m/1000).toFixed(1)} km`;}
const places=computed(()=>[...(additions.value?.items??[]),...(attractions.value?.items??[]).map(p=>({...p,category:'Attractions'}))]);
const suggestions=computed(()=>{const q=query.value.toLowerCase().trim();if(!q)return [];return places.value.filter(p=>(category.value==='All'||p.category===category.value)&&`${p.name} ${p.address} ${p.area??''} ${p.category}`.toLowerCase().includes(q)).slice(0,6);});
function chooseSuggestion(p:Place){query.value=p.name;suggestionsOpen.value=false;activeSuggestion.value=-1;}
function searchKeys(e:KeyboardEvent){if(e.key==='Escape'){suggestionsOpen.value=false;return;}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();suggestionsOpen.value=true;const n=suggestions.value.length;if(n)activeSuggestion.value=(activeSuggestion.value+(e.key==='ArrowDown'?1:-1)+n)%n;}if(e.key==='Enter'&&suggestionsOpen.value&&activeSuggestion.value>=0){e.preventDefault();const p=suggestions.value[activeSuggestion.value];if(p)chooseSuggestion(p);}}
function blurSearch(){setTimeout(()=>{suggestionsOpen.value=false;},150);}
// What's near me: one-shot fix, kept in memory on this device only. Distances are worked out in the browser; coordinates are never sent or saved.
const here=ref<{lat:number;lon:number}|null>(null); const nearBusy=ref(false); const nearMsg=ref('');
async function findNearMe(){
if(nearBusy.value)return; nearMsg.value='';
if(!navigator.geolocation){nearMsg.value='Location is not supported in this browser. Browse or search the list instead.';return;}
nearBusy.value=true;
try{
const fix=await new Promise<GeolocationPosition>((resolve,reject)=>{navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:10000,maximumAge:60000});});
if(Date.now()-fix.timestamp>120000||fix.coords.accuracy>1000){nearMsg.value='Your location is too old or imprecise. Try again, or browse the list.';return;}
const c={lat:fix.coords.latitude,lon:fix.coords.longitude};
if(!Number.isFinite(c.lat)||!Number.isFinite(c.lon)||!isInSingapore(c)){nearMsg.value='You seem to be outside Singapore, so nearby places are not shown. Browse the list instead.';return;}
here.value=c;limit.value=12;expanded.value=null;
}catch(e){const code=(e as {code?:number}).code;nearMsg.value=code===1?'Location permission was declined. Allow location in your browser settings, or browse the list.':'Could not get your location. Try again, or browse the list.';}
finally{nearBusy.value=false;}
}
function clearNear(){here.value=null;nearMsg.value='';limit.value=12;expanded.value=null;}
const matches=computed(()=>places.value.filter(p=>(category.value==='All'||p.category===category.value)&&`${p.name} ${p.address} ${p.area??''} ${p.category}`.toLowerCase().includes(query.value.toLowerCase().trim())));
const unranked=computed(()=>here.value?matches.value.filter(p=>p.closed||typeof p.lat!=='number'||typeof p.lon!=='number').length:0);
const filtered=computed(()=>{const h=here.value;if(!h)return matches.value.map(p=>({...p,distance:undefined}));
return matches.value.filter(p=>!p.closed&&typeof p.lat==='number'&&typeof p.lon==='number').map(p=>({...p,distance:haversineM(h,{lat:p.lat as number,lon:p.lon as number})})).sort((a,b)=>a.distance-b.distance);});
watch([query,category],()=>{limit.value=12;expanded.value=null;});
function lineChips(name:string){return rail.value?.lines.filter(l=>l.stations.some(s=>s.name===name))??[];}
function mrtOptions(p:Place){return p.mrtOptions??(p.transportStations??(p.mrt?[p.mrt.name]:[])).map(name=>({name,entrance:'',access:p.category==='Attractions'?'': 'Official station option; onward travel may be needed. Check the official visit information.'}));}
</script>
<template>
<div class="bg"><main class="pg">
<h1>Explore</h1><p class="intro">Places to enjoy, nearby or across Singapore.</p>
<div class="controls"><div class="search-wrap"><input v-model="query" type="search" placeholder="Search places" aria-label="Search places" role="combobox" aria-autocomplete="list" aria-controls="place-suggestions" :aria-expanded="suggestionsOpen && suggestions.length>0" :aria-activedescendant="activeSuggestion>=0 ? `suggestion-${activeSuggestion}` : undefined" @input="suggestionsOpen=true;activeSuggestion=-1" @focus="suggestionsOpen=true" @blur="blurSearch" @keydown="searchKeys"/><ul v-if="suggestionsOpen && suggestions.length" id="place-suggestions" class="suggestions" role="listbox" aria-label="Matching places"><li v-for="(p,i) in suggestions" :id="`suggestion-${i}`" :key="p.name" role="option" :aria-selected="activeSuggestion===i" @mousedown.prevent="chooseSuggestion(p)" @touchend.prevent="chooseSuggestion(p)" @click="chooseSuggestion(p)"><span>{{p.name}}</span><small>{{p.category}}</small></li></ul></div><div class="near-row"><button type="button" class="go near-btn" :disabled="nearBusy" @click="findNearMe">{{nearBusy?'Finding your location...':here?'Refresh near me':"What's near me"}}</button><button v-if="here" type="button" class="clear-near" @click="clearNear">Show all</button></div><p class="status" role="status" aria-live="polite">{{nearMsg||(here?'Nearest first, in a straight line, not walking time. Closed places and places without a mapped point are left out.':'Tap to list parks, libraries and attractions closest to you. Your location stays on your device and is not saved.')}}</p><div class="control-row"><select v-model="category" aria-label="Category"><option>All</option><option>Attractions</option><option>Libraries</option><option>Parks</option></select></div></div>

<p class="preview-note">Original concept illustrations, not photographs or views of the named sites. Check official visit information for current access.</p>
<details v-if="additions?.coverage" class="coverage"><summary>{{additions.coverage.parkDestinations}} park destinations · {{additions.coverage.libraries}} libraries · Coverage and gaps</summary><p>Official-directory coverage: {{additions.coverage.parkDestinations}} NParks destinations (including gardens, playgrounds and open spaces) and {{additions.coverage.libraries}} libraries. {{additions.coverage.excludedConnectorTrails}} connector/trail-only listings excluded. {{additions.coverage.closedLibraries}} libraries are temporarily closed. {{additions.coverage.parkTransportPending}} park entries still need entrance-level transport checks. This is not a list of every municipal/private park or school/university library.</p></details>
<p class="count">{{filtered.length}} places<template v-if="here">, nearest first<template v-if="unranked"> · {{unranked}} not ranked</template></template></p>
<div class="places"><article v-for="p in filtered.slice(0,limit)" :key="p.name" class="place"><div class="place-top"><figure class="thumb"><img :src="p.previewImage ?? `/img/attractions/${p.img}-320.webp`" :alt="`Illustration for ${p.name}, not an entrance photo`" width="320" height="180"/></figure><div class="card-copy"><span class="meta">{{p.category}}{{p.area?' · '+p.area:''}}<template v-if="p.distance!==undefined"> · <strong class="distance">{{fmt(p.distance)}} away</strong></template></span><h2>{{p.name}}</h2><p v-if="p.closed" class="closure">Temporarily closed</p><p v-if="p.transportPending" class="status">Transport check pending</p><p class="description">{{p.description??p.address}}</p></div><button class="go" :aria-expanded="expanded===p.name" @click="expanded=expanded===p.name?null:p.name">{{expanded===p.name?'Close':p.closed?'Details':'Go there'}}</button></div>
<div v-if="expanded===p.name" class="details"><img v-if="p.img || p.previewImage" :src="p.previewImage ?? `/img/attractions/${p.img}-640.webp`" :alt="`Illustration of ${p.name}`" width="640" height="360"/><p>{{p.address}}</p><p v-if="p.note">{{p.note}}</p><div v-for="m in (p.closed ? [] : mrtOptions(p))" :key="m.name" class="transport"><div><span v-for="line in lineChips(m.name)" :key="line.code" class="chip" :style="{background:line.color}">{{line.code}}</span><strong>{{m.name}}</strong><p>{{m.entrance}} {{m.access}}</p></div><NuxtLink :to="`/mrt?to=${encodeURIComponent(m.name)}`" class="go">Go by MRT</NuxtLink></div><div v-if="p.bus && !p.closed" class="transport"><div><strong>{{p.bus.name}}</strong><p>Stop {{p.bus.code}}<template v-if="p.bus.dist!==undefined"> · {{fmt(p.bus.dist)}} from listed point, not walking distance</template><template v-if="p.bus.access"> · {{p.bus.access}}</template></p></div><NuxtLink :to="`/bus?stop=${p.bus.code}`" class="go">Bus arrivals</NuxtLink></div><details v-if="p.walkRoute && !p.closed" class="walk-route"><summary>{{p.walkRoute.kind}} · {{p.walkRoute.meters}} m · about {{p.walkRoute.minutes}} min</summary><p>Map-estimated route to {{p.walkRoute.endpoint}}, not a verified entrance or step-free route.</p><ol><li v-for="(step,i) in p.walkRoute.steps" :key="i">{{step}}</li></ol><a :href="p.walkRoute.url" target="_blank" rel="noopener noreferrer">Walking directions</a><p v-if="p.walkRoute.warnings.length" class="status">{{p.walkRoute.warnings.join(" ")}}</p></details><p v-if="!p.closed && !p.bus && p.category!=='Attractions'" class="status">Bus-stop access is not verified for this listing. Check official visit information.</p><p v-if="p.officialUrl"><a :href="p.officialUrl" target="_blank" rel="noopener noreferrer">Official visit information</a> · Checked {{p.checkedAt}}</p><p v-if="p.transportSources?.length" class="status">Transport checked {{p.checkedAt}} · <a v-for="(url,i) in p.transportSources" :key="url" :href="url" target="_blank" rel="noopener noreferrer">{{i ? " / " : ""}}Source {{i+1}}</a></p><p v-if="p.datasetUrl" class="status"><a :href="p.datasetUrl" target="_blank" rel="noopener noreferrer">Location dataset</a> · indicative point, not a verified entrance</p></div></article></div>
<p v-if="!filtered.length" role="status">{{here?'Nothing nearby matches. Try another category or tap Show all.':'No matches. Try another category or search.'}}</p><button v-if="filtered.length>limit" class="more" @click="limit+=12">Show more</button>
<p class="source">Park and library information checked against official NParks and NLB visit pages on 1 October 2026. Individual source links are in the place details. Illustrations are original concept art, not agency photos or verified entrance images.</p><DataCredits/>
</main></div>
</template>
<style scoped>
