r(--md-sys-color-outline-variant)}.walk-route summary{cursor:pointer;font-weight:600}.walk-route li{margin:7px 0}.coverage{font-size:12px;line-height:1.5;margin:12px 0;color:var(--md-sys-color-on-surface-variant)}.coverage summary{cursor:pointer}.coverage p{margin:8px 0}.closure{font-size:12px;font-weight:650;color:var(--sg-brand-text);margin:5px 0}.card-copy{min-width:0}.place-top>.go{grid-column:2;justify-self:end}.place-top h2{margin-top:3px}.meta,.distance{font-size:12px;color:var(--md-sys-color-on-surface-variant)}h2{font-size:17px;margin:5px 0;font-weight:650}.description{font-size:13px;line-height:1.45;margin:0}.go,.more{display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;min-height:44px;box-sizing:border-box;background:var(--sg-brand-strong);color:#fff;border:0;border-radius:10px;padding:10px 12px;font:inherit;font-size:13px;font-weight:600;text-decoration:none;cursor:pointer}.details{border-top:1px solid var(--md-sys-color-outline-variant);margin-top:14px;padding-top:14px;font-size:13px;line-height:1.5}.details img{width:100%;height:auto;border-radius:12px}.transport{display:flex;align-items:center;justify-content:space-between;gap:12px;border-top:1px solid var(--md-sys-color-outline-variant);padding:10px 0}.transport p{margin:4px 0}.status,.source{font-size:12px;line-height:1.5;color:var(--md-sys-color-on-surface-variant)}.chip{display:inline-block;padding:2px 5px;border-radius:5px;color:#fff;font-size:11px;margin-right:5px;font-weight:700}.gate{padding:10px;background:var(--md-sys-color-surface-container);border-radius:8px}.more{display:flex;margin:18px auto}.source{margin:22px 0}a{color:var(--sg-brand-text)}.go{color:#fff}:is(button,input,select,a):focus-visible{outline:3px solid var(--sg-brand-text);outline-offset:3px}@media(min-width:768px){.place-top{grid-template-columns:88px minmax(0,1fr) auto;align-items:center}.thumb{grid-row:1}.place-top>.go{grid-column:3;align-self:center}}@media(max-width:767px){.pg{padding:18px 14px;border-radius:0}.places{grid-template-columns:1fr}.place{padding:14px}.intro{margin-bottom:16px}.search-wrap{position:relative}.suggestions{position:absolute;z-index:5;top:100%;left:0;right:0;list-style:none;margin:4px 0 0;padding:5px;background:var(--md-sys-color-surface-container-lowest);border:1px solid var(--md-sys-color-outline-variant);border-radius:12px;box-shadow:0 5px 16px #0002}.suggestions li{display:flex;justify-content:space-between;gap:8px;align-items:center;padding:12px 9px;border-radius:7px;cursor:pointer;font-size:14px}.suggestions li:hover,.suggestions li[aria-selected=true]{background:var(--md-sys-color-surface-container)}.suggestions small{font-size:11px;color:var(--md-sys-color-on-surface-variant)}.preview-note{line-height:1.5}}
.near-row{display:flex;justify-content:flex-end;align-items:center;gap:12px;margin-top:10px}.clear-near{background:none;border:0;color:var(--sg-brand-text);font:inherit;font-size:13px;font-weight:600;min-height:44px;padding:0 6px;cursor:pointer;text-decoration:underline}.near-btn:disabled{opacity:.6;cursor:progress}.distance strong,strong.distance{color:var(--sg-brand-text)}
</style>
